firebase_script = """<script type="module">
import { initializeApp, getApps, getApp } from 'https://www.gstatic.com/firebasejs/10.7.0/firebase-app.js';
import { getFirestore, collection, addDoc, serverTimestamp } from 'https://www.gstatic.com/firebasejs/10.7.0/firebase-firestore.js';
const firebaseConfig = {
  apiKey: "REPLACE_WITH_FIREBASE_API_KEY",
  authDomain: "REPLACE_WITH_AUTH_DOMAIN",
  projectId: "REPLACE_WITH_PROJECT_ID",
  storageBucket: "REPLACE_WITH_STORAGE_BUCKET",
  messagingSenderId: "REPLACE_WITH_SENDER_ID",
  appId: "REPLACE_WITH_APP_ID"
};
const app = getApps().length ? getApp() : initializeApp(firebaseConfig);
const db = getFirestore(app);
document.getElementById('hostForm').addEventListener('submit', async function(e) {
  e.preventDefault();
  const btn = document.getElementById('submitBtn');
  const successMsg = document.getElementById('successMsg');
  const errorMsg = document.getElementById('errorMsg');
  successMsg.style.display = 'none'; errorMsg.style.display = 'none';
  btn.disabled = true; btn.innerHTML = '<span class="spinner"></span>Submitting\u2026';
  try {
    await addDoc(collection(db, 'hostApplications'), {
      name: this.name.value.trim(), city: this.city.value.trim(),
      phone: this.phone.value.trim(), language: this.language.value,
      about: this.about.value.trim(), status: 'pending', submittedAt: serverTimestamp()
    });
    successMsg.style.display = 'block'; this.reset();
  } catch(err) { console.error('Firestore write failed:', err); errorMsg.style.display = 'block'; }
  finally { btn.disabled = false; btn.textContent = 'Submit application'; }
});
</script>"""

i18n_script = """<script>
const I18N={};let currentLang='en';
function t(k,f){f=f||'';var keys=k.split('.'),val=I18N[currentLang];for(var i=0;i<keys.length;i++){if(val==null)break;val=val[keys[i]];}if(val!=null)return val;val=I18N['en'];for(i=0;i<keys.length;i++){if(val==null)break;val=val[keys[i]];}return val!=null?val:f;}
function switchLang(lang){currentLang=lang;document.querySelectorAll('.lang-btn').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));applyTranslations();localStorage.setItem('friendoo_lang',lang);}
function setText(sel,text){var el=document.querySelector(sel);if(el)el.textContent=text;}
function setHtml(sel,html){var el=document.querySelector(sel);if(el)el.innerHTML=html;}
function applyTranslations(){
  ['nav.features','nav.tiers','nav.pricing','nav.apply','nav.join','hero.eyebrow','hero.sub','hero.cta1','hero.cta2','features.label','features.title','tiers.label','tiers.title','tiers.lead','tiers.normal.badge','tiers.normal.title','tiers.normal.earnSub','tiers.star.badge','tiers.star.title','tiers.star.earnSub','steps.label','steps.title','potential.label','potential.title','potential.lead','hosts.label','hosts.title','pricing.label','pricing.title','form.label','form.title','form.lead'].forEach(k=>setText('[data-t="'+k+'"]',t(k)));
  renderDynamic();
}
function renderDynamic(){
  var f=t('features.cards',[]);var fi='';for(var i=0;i<f.length;i++)fi+='<div class="feat-card"><div class="feat-icon">'+f[i].icon+'</div><h3>'+f[i].title+'</h3><p>'+f[i].desc+'</p></div>';
  setHtml('#featInner1',fi);setHtml('#featInner2',fi);
  var s=t('stats',[]);var sr='';for(i=0;i<s.length;i++)sr+='<div class="stat-box"><div class="stat-num">'+s[i].num+'</div><div class="stat-label">'+s[i].label+'</div></div>';setHtml('#statsRow',sr);
  var np=t('tiers.normal.points',[]);var npu='';for(i=0;i<np.length;i++)npu+='<li>'+np[i]+'</li>';setHtml('#normalPoints',npu);
  var sp=t('tiers.star.points',[]);var spu='';for(i=0;i<sp.length;i++)spu+='<li>'+sp[i]+'</li>';setHtml('#starPoints',spu);
  var st=t('steps.steps',[]);var sg='';for(i=0;i<st.length;i++)sg+='<div class="step-card"><div class="step-num">'+st[i].num+'</div><h4>'+st[i].title+'</h4><p>'+st[i].desc+'</p></div>';setHtml('#stepsGrid',sg);
  var pc=t('potential.cards',[]);var pg='';for(i=0;i<pc.length;i++){pg+='<div class="potential-card"><h4>'+pc[i].title+'</h4><table>';var rows=pc[i].rows||[];for(var j=0;j<rows.length;j++){var pts=rows[j].split('|');pg+='<tr><td>'+pts[0]+'</td><td>'+pts[1]+'</td></tr>';}pg+='</table><div class="prob-label"><span>Low</span><span>High</span></div><div class="prob-bar"><div class="prob-fill" style="width:'+pc[i].bar+';background:linear-gradient(to right,var(--brand),var(--teal))"></div></div></div>';}setHtml('#potentialGrid',pg);
  var ht=t('hosts.cards',[]);var hv='';for(i=0;i<ht.length;i++){var tc=ht[i].tier==='STAR'?'#ffd700':'rgba(255,255,255,.7)';var tb=ht[i].tier==='STAR'?'rgba(255,215,0,.2)':'rgba(255,255,255,.1)';hv+='<div class="host-card"><div style="display:flex;align-items:center;gap:14px;margin-bottom:12px"><div style="width:52px;height:52px;border-radius:50%;background:linear-gradient(135deg,var(--brand),var(--pink));flex-shrink:0"></div><div><strong>'+ht[i].name+'</strong><div style="font-size:13px;color:var(--muted)">'+ht[i].loc+' &bull; &starf; '+ht[i].rating+'</div></div><div style="margin-left:auto;padding:5px 11px;border-radius:999px;background:'+tb+';color:'+tc+';font-size:11px;font-weight:700">'+ht[i].tier+'</div></div><div class="host-tag">';for(j=0;j<ht[i].tags.length;j++)hv+='<span class="tag">'+ht[i].tags[j]+'</span>';hv+='</div><div style="margin-top:14px"><div style="display:flex;justify-content:space-between;font-size:13px;color:var(--muted);margin-bottom:6px"><span>This month</span><span>'+ht[i].earn+'</span></div><div class="bar-bg"><div class="bar-fill" style="width:'+ht[i].bar+'"></div></div></div></div>';}setHtml('#hostVisual',hv);
  var pr=t('pricing.cards',[]);var pg2='';for(i=0;i<pr.length;i++){pg2+='<div class="price-card'+(i===1?' hot':'')+'"><div class="pill">'+pr[i].pill+'</div><div class="amount">'+pr[i].amount+'</div><div class="coins">'+pr[i].coins+'</div><ul>';for(j=0;j<pr[i].points.length;j++)pg2+='<li>'+pr[i].points[j]+'</li>';pg2+='</ul><a class="btn" href="#apply" style="margin-top:18px;width:100%;text-align:center;display:block;padding:14px;border-radius:999px">'+pr[i].cta+'</a></div>';}setHtml('#pricingGrid',pg2);
  var lo=t('form.fields.3.options',[]);if(lo.length)setHtml('#langSelect',lo.map(o=>'<option>'+o+'</option>').join(''));
  var cy=t('hero.cycle',[]);if(cy.length)setHtml('#cycleText',cy.map(c=>'<span>'+c+'</span>').join('')+'<span>'+cy[0]+'</span>');
}
function calc(){var tier=parseFloat(document.getElementById('tier').value)||0,days=parseFloat(document.getElementById('days').value)||0,hours=parseFloat(document.getElementById('hours').value)||0,avgMin=parseFloat(document.getElementById('avgMin').value)||1,totalMin=Math.round(days*hours*60),calls=Math.round(totalMin/avgMin);document.getElementById('cCalls').textContent=calls.toLocaleString('en-IN');document.getElementById('cMinutes').textContent=totalMin.toLocaleString('en-IN');document.getElementById('cEarnings').textContent='\u20b9'+Math.round(totalMin*tier).toLocaleString('en-IN');}
['tier','days','hours','avgMin'].forEach(id=>{document.getElementById(id).addEventListener('input',calc);document.getElementById(id).addEventListener('change',calc);});calc();
document.addEventListener('DOMContentLoaded',function(){var saved=localStorage.getItem('friendoo_lang');if(saved&&I18N[saved])currentLang=saved;applyTranslations();});
</script>"""

